<script setup>
import { ref, computed, reactive, watch, onUnmounted } from 'vue'
import { ElDialog, ElInputNumber, ElProgress, ElMessage, ElMessageBox } from 'element-plus'
import 'element-plus/dist/index.css'
import { LayoutDashboard, ClipboardCheck, Sparkles, Trophy, Users, Settings, Bell, ArrowUpRight, Upload, CircleAlert, CheckCircle2, Menu, X, ChevronDown, Download, ArrowLeft, Search, Plus } from 'lucide-vue-next'
import {state, persistence, dimensions, currentStudent, score, downloadCsv, allowedRegistration, seed} from './data'
import './workspace.css'
const props=defineProps({initial:String}),emit=defineEmits(['home'])
const active=ref(props.initial||'overview'),role=ref(['register','results'].includes(props.initial)?'student':'admin'),mobileOpen=ref(false),contrast=ref(false),query=ref(''),filter=ref('全部状态'),detail=ref(null),settingsOpen=ref(false),competitionModal=ref(false),notificationOpen=ref(false),busy=ref(false),runProgress=ref(0),scanReady=ref(false),preview=ref('')
const reviewOpen=computed({get:()=>!!detail.value,set:v=>{if(!v)detail.value=null}})
const settingsWeights=ref([...state.weights]),selectedWorkId=ref(''),editingId=ref(null)
const adminNav=[{id:'overview',label:'总览面板',en:'Overview',icon:LayoutDashboard},{id:'verify',label:'报名材料检验',en:'Verification',icon:ClipboardCheck},{id:'evaluate',label:'成果智能评价',en:'Evaluation',icon:Sparkles},{id:'competitions',label:'竞赛管理',en:'Competitions',icon:Trophy},{id:'students',label:'参赛学生',en:'Participants',icon:Users}]
const studentNav=[{id:'overview',label:'我的工作台',en:'Overview',icon:LayoutDashboard},{id:'competitions',label:'发现竞赛',en:'Explore',icon:Trophy},{id:'register',label:'在线报名',en:'Registration',icon:ClipboardCheck},{id:'evaluate',label:'提交作品',en:'Submission',icon:Upload},{id:'results',label:'我的结果',en:'Results',icon:Sparkles}]
const nav=computed(()=>role.value==='admin'?adminNav:studentNav),pageTitle=computed(()=>nav.value.find(x=>x.id===active.value)?.label||'工作台')
const mine=computed(()=>state.registrations.filter(r=>r.studentId===currentStudent.studentId))
const visibleRecords=computed(()=>role.value==='admin'?state.registrations:mine.value)
const filtered=computed(()=>visibleRecords.value.filter(r=>(filter.value==='全部状态'||r.status===filter.value)&&[r.name,r.studentId,contestName(r.contestId)].join(' ').includes(query.value)))
const competitions=computed(()=>state.competitions.filter(c=>[c.name,c.category,c.phase].join(' ').toLowerCase().includes(query.value.toLowerCase())))
const visibleWorks=computed(()=>role.value==='admin'?state.works:state.works.filter(w=>w.studentId===currentStudent.studentId))
const selectedWork=computed(()=>visibleWorks.value.find(w=>w.id===selectedWorkId.value))
const pending=computed(()=>state.registrations.filter(r=>['待检验','待复核','疑似异常'].includes(r.status)).length)
const passed=computed(()=>visibleRecords.value.filter(r=>r.status==='已通过').length)
const passRate=computed(()=>visibleRecords.value.length?Math.round(passed.value/visibleRecords.value.length*1000)/10:0)
const evaluated=computed(()=>visibleWorks.value.filter(w=>role.value==='admin'?(w.finalScores||w.aiScores):w.published))
const average=computed(()=>evaluated.value.length?(evaluated.value.reduce((sum,w)=>sum+score(w.finalScores||w.aiScores,w.weights||state.weights),0)/evaluated.value.length).toFixed(1):'—')
const participants=computed(()=>{const map=new Map();for(const r of state.registrations){if(!map.has(r.studentId))map.set(r.studentId,{name:r.name,id:r.studentId,count:0,passed:0});const p=map.get(r.studentId);p.count++;if(r.status==='已通过')p.passed++}return [...map.values()].filter(p=>(p.name+p.id).includes(query.value))})
const registration=reactive({name:currentStudent.name,studentId:currentStudent.studentId,contestId:'c1',team:'',certificate:'在读证明',award:'无',issuer:'温州商学院'})
const work=reactive({registrationId:'',title:'',summary:''})
const formFiles=ref([]),workFiles=ref([]),fileInput=ref(null),workInput=ref(null),ocr=reactive({name:'',studentId:'',certificate:'',award:'',issuer:''}),reviewNote=ref(''),reviewScores=ref([85,82,88,84]),reviewComments=ref('')
const fieldLabels={name:'姓名',studentId:'学号',certificate:'证书名称',award:'获奖等级',issuer:'颁发单位'}
const competition=reactive({name:'',category:'计算机 / 算法',deadline:'2026-12-01',phase:'报名中',description:'',requirements:''})
const notifications=computed(()=>[{title:pending.value+' 份报名材料待处理',body:'查看、比对材料信息并完成复核。',target:'verify'},{title:state.works.filter(w=>w.status==='待评价').length+' 份作品等待评价',body:'评价结果须经过教师复核后发布。',target:'evaluate'}])
let timer;const uploadUrls=[]
function navigate(id){active.value=id;query.value='';filter.value='全部状态';mobileOpen.value=false;location.hash='/workspace/'+id;scrollTo({top:0,behavior:'instant'})}
watch(()=>props.initial,v=>{active.value=v})
watch(role,()=>{navigate('overview');detail.value=null;selectedWorkId.value='';scanReady.value=false})
watch(selectedWork,w=>{if(w){reviewScores.value=[...(w.finalScores||w.aiScores||[85,82,88,84])];reviewComments.value=w.comments||''}})
function contestName(id){return state.competitions.find(c=>c.id===id)?.name||'已归档竞赛'}
function statusClass(status){return status==='已通过'||status==='已发布'?'pass':status==='疑似异常'||status==='不通过'?'warn':'pending'}
function time(value){return new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function pickFiles(files,target){const accepted=[];for(const f of files){const ext=f.name.split('.').pop().toLowerCase();const allowed=target==='work'?['pdf','docx','txt','zip','png','jpg','jpeg']:['pdf','png','jpg','jpeg'];if(!allowed.includes(ext)||f.size>20*1024*1024){ElMessage.error(f.name+'：格式不支持或超过 20MB');continue}if(accepted.length+(target==='work'?workFiles.value.length:formFiles.value.length)>=20){ElMessage.warning('最多上传 20 个文件');break}accepted.push({name:f.name,size:f.size,type:f.type});if(target!=='work'&&f.type.startsWith('image/')){if(preview.value)URL.revokeObjectURL(preview.value);preview.value=URL.createObjectURL(f);uploadUrls.push(preview.value)}}if(target==='work')workFiles.value.push(...accepted);else formFiles.value.push(...accepted)}
function submitRegistration(){if(!registration.name.trim()||!/^\d{8,14}$/.test(registration.studentId)){ElMessage.error('请填写姓名及 8–14 位数字学号');return}const c=state.competitions.find(c=>c.id===registration.contestId);if(!c||!allowedRegistration(c)){ElMessage.error('此竞赛当前不可报名');return}if(!formFiles.value.length){ElMessage.error('请至少上传一份报名材料');return}if(state.registrations.some(r=>r.contestId===registration.contestId&&r.studentId===registration.studentId&&r.status!=='不通过')){ElMessage.warning('该学号已报名此竞赛，请在我的结果中查看');return}state.registrations.unshift({...registration,id:crypto.randomUUID(),status:'待检验',submittedAt:new Date().toISOString(),files:[...formFiles.value],history:[]});formFiles.value=[];preview.value='';ElMessage.success('报名已保存在此浏览器，等待材料检验');navigate('results')}
function openReview(r){detail.value=r;reviewNote.value='';scanReady.value=!!r.ocr;Object.assign(ocr,r.ocr||{name:'',studentId:'',certificate:'',award:'',issuer:''})}
function startScan(){if(!detail.value||busy.value)return;busy.value=true;runProgress.value=0;scanReady.value=false;timer=setInterval(()=>{runProgress.value+=20;if(runProgress.value>=100){clearInterval(timer);busy.value=false;scanReady.value=true;const r=detail.value;if(!r)return;Object.assign(ocr,r.ocr||{name:'示例同学',studentId:'2026000000',certificate:'在读证明',award:'无',issuer:'示例大学'});ElMessage.info('已载入示例识别结果。未调用 OCR 服务。')}},180)}
function compare(){const r=detail.value;if(!r)return;const norm=v=>String(v||'').trim();r.checks=Object.keys(fieldLabels).filter(k=>r[k]!==undefined).map(k=>({key:k,expected:r[k],actual:ocr[k],match:!!norm(ocr[k])&&norm(r[k])===norm(ocr[k])}));r.ocr={...ocr};r.status=r.checks.every(x=>x.match)?'待复核':'疑似异常';r.history.push({at:new Date().toISOString(),action:'字段一致性比对',note:r.checks.filter(x=>x.match).length+'/'+r.checks.length+' 项一致；识别值为演示输入。'});ElMessage.success('已完成字段比对，最终结论请人工复核')}
function resolveReview(result){if(!reviewNote.value.trim()){ElMessage.warning('请填写复核意见');return}const r=detail.value;r.status=result;r.history.push({at:new Date().toISOString(),action:'人工复核：'+result,note:reviewNote.value});ElMessage.success('复核结果已保存');detail.value=null}
function submitWork(){const r=mine.value.find(r=>r.id===work.registrationId&&r.status==='已通过');if(!r){ElMessage.warning('请选择已通过报名审核的项目');return}if(!work.title.trim()||work.summary.trim().length<20){ElMessage.warning('请填写作品标题和至少 20 字摘要');return}if(!workFiles.value.length){ElMessage.warning('请上传作品文件');return}state.works.unshift({id:crypto.randomUUID(),registrationId:r.id,contestId:r.contestId,name:r.name,studentId:r.studentId,title:work.title,summary:work.summary,files:[...workFiles.value],status:'待评价',published:false,history:[]});workFiles.value=[];work.title='';work.summary='';ElMessage.success('作品已保存至本地演示队列');navigate('results')}
function runEvaluation(){const w=selectedWork.value;if(!w||busy.value)return;busy.value=true;runProgress.value=0;timer=setInterval(()=>{runProgress.value+=20;if(runProgress.value>=100){clearInterval(timer);busy.value=false;w.aiScores=[85,82,88,84];w.weights=[...state.weights];w.finalScores=null;w.status='待复核';w.published=false;w.comments='演示评语：建议进一步明确创新点，补充技术对照实验与应用验证。此评语为预设示例，不代表对上传作品的真实评价。';w.history.push({at:new Date().toISOString(),action:'生成示例评价',note:'固定演示评分 85 / 82 / 88 / 84，未调用大模型。'});reviewScores.value=[...w.aiScores];reviewComments.value=w.comments}},200)}
function saveReview(){const w=selectedWork.value;if(!w?.aiScores)return;if(reviewScores.value.some(n=>typeof n!=='number'||n<0||n>100)){ElMessage.error('分值必须在 0–100 之间');return}if(!reviewComments.value.trim()){ElMessage.warning('请填写评价意见');return}const before=w.finalScores||w.aiScores;w.finalScores=[...reviewScores.value];w.comments=reviewComments.value;w.status='已复核';w.published=false;w.history.push({at:new Date().toISOString(),action:'教师复核',note:before.join('/')+' → '+w.finalScores.join('/')});ElMessage.success('评分与复核意见已保存')}
function publish(){const w=selectedWork.value;if(w?.status!=='已复核'){ElMessage.warning('请先保存教师复核结果');return}w.published=true;w.status='已发布';w.history.push({at:new Date().toISOString(),action:'发布成绩',note:'学生端可以查看已发布结果。'});ElMessage.success('评价结果已发布')}
function exportRegistrations(){downloadCsv('竞序_报名数据.csv',['姓名','学号','竞赛','状态','提交时间'],visibleRecords.value.map(r=>[r.name,r.studentId,contestName(r.contestId),r.status,r.submittedAt]));ElMessage.success('报名 CSV 已导出')}
function exportReport(w){if(!w)return;const scores=w.finalScores||w.aiScores;downloadCsv('竞序_评价报告.csv',['作品','维度','得分','权重','说明'],dimensions.map((d,i)=>[w.title,d,scores?.[i]??'',(w.weights||state.weights)[i]+'%',w.comments]).concat([[w.title,'总分',score(scores,w.weights||state.weights)?.toFixed(1)||'未评价','100%','演示评价；不是真实 AI 推理结果']]))}
function editCompetition(c){editingId.value=c?.id||null;Object.assign(competition,c||{name:'',category:'计算机 / 算法',deadline:'2026-12-01',phase:'报名中',description:'',requirements:''});competitionModal.value=true}
function saveCompetition(){if(!competition.name.trim()||!competition.deadline||!competition.description.trim()){ElMessage.warning('请填写名称、截止日期与说明');return}if(editingId.value)Object.assign(state.competitions.find(c=>c.id===editingId.value),competition);else state.competitions.push({...competition,id:crypto.randomUUID()});competitionModal.value=false;ElMessage.success('竞赛配置已保存')}
function openSettings(){settingsWeights.value=[...state.weights];settingsOpen.value=true}
function saveSettings(){if(settingsWeights.value.some(x=>typeof x!=='number'||x<0)||settingsWeights.value.reduce((s,x)=>s+x,0)!==100){ElMessage.warning('评价权重须为非负数，合计为 100%');return}state.weights=[...settingsWeights.value];settingsOpen.value=false;ElMessage.success('评价权重已保存；已生成报告保留原权重')}
async function reset(){try{await ElMessageBox.confirm('这会清除此浏览器的演示记录并恢复初始示例。','重置演示',{confirmButtonText:'确认重置',cancelButtonText:'取消',type:'warning'});Object.assign(state,structuredClone(seed));settingsOpen.value=false;ElMessage.success('演示数据已重置')}catch{}}
function registerContest(c){role.value='student';registration.contestId=c.id;setTimeout(()=>navigate('register'),0)}
onUnmounted(()=>{clearInterval(timer);uploadUrls.forEach(u=>URL.revokeObjectURL(u))})
</script>

<template>
<div class="app workspace" :class="{contrast}">
 <aside class="sidebar" :class="{open:mobileOpen}"><button class="brand home-brand" @click="emit('home')"><div class="brand-mark">竞</div><div><b>竞序</b><span>COMPETE / INTEL STUDIO</span></div></button><button class="close-mobile" aria-label="关闭菜单" @click="mobileOpen=false"><X/></button><div class="side-rule"><span>{{role==='admin'?'CONTROL CENTER':'STUDENT SPACE'}}</span><i></i><span>DEMO</span></div><nav><button v-for="item in nav" :key="item.id" :class="{active:active===item.id}" @click="navigate(item.id)"><component :is="item.icon" :size="18"/><span><strong>{{item.label}}</strong><small>{{item.en}}</small></span><em v-if="item.id==='verify'">{{pending}}</em><ArrowUpRight v-else-if="active===item.id" class="nav-arrow" :size="15"/></button></nav><div class="side-bottom"><button class="back-home" @click="emit('home')"><ArrowLeft :size="15"/>返回展示首页</button><div class="system"><span class="pulse"></span><span>本地交互演示</span><small>MOCK / NO BACKEND CONNECTED</small></div><button v-if="role==='admin'" class="settings" @click="openSettings"><Settings :size="17"/>评价规则设置</button><div class="profile"><div class="avatar">吴</div><div><b>吴直良</b><span>{{role==='admin'?'管理端演示':'学生端演示'}}</span></div><ChevronDown :size="15"/></div></div></aside>
 <main class="main"><header class="topbar"><button class="menu-mobile" aria-label="打开菜单" @click="mobileOpen=true"><Menu/></button><div class="crumb"><span>竞序 /</span><b>{{pageTitle}}</b></div><div class="top-actions"><label class="role-switch"><span>演示身份</span><select v-model="role" aria-label="切换演示身份"><option value="admin">教师 / 管理端</option><option value="student">学生端</option></select></label><button class="icon-btn" aria-label="查看待办通知" @click="notificationOpen=true"><Bell :size="18"/><i></i></button><button class="contrast-btn" @click="contrast=!contrast" :aria-pressed="contrast">◐ 对比</button></div></header>
 <div class="demo-notice"><span>DEMO / 前端原型</span> 数据保存在当前浏览器。OCR 与大模型为显式模拟，最终结果需人工复核。<span v-if="persistence.error" class="error-text">{{persistence.error}}</span></div>
 <div class="page">
 <template v-if="active==='overview'"><section class="hero"><div><p class="eyebrow">CAMPUS COMPETITION / INTELLIGENCE STUDIO</p><h1>让每一份<br/><i>创造</i>被看见<span class="dot">.</span></h1><p class="lede">{{role==='admin'?'从材料核验到成果评价，让判断更有依据。':'从一个想法出发，开启你的下一场竞赛。'}}</p></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="orbit o1"></div><div class="orbit o2"></div><div class="binary">01001 11010 00101<br/>11001 00110 10110</div><span class="art-label">AI / HUMAN<br/>COLLABORATION</span></div></section><div class="signal"><span>AI CONSOLE / 竞赛智能中枢</span><div class="signal-line"><i v-for="n in 12" :key="n"></i></div><b>LOCAL DEMO</b></div><section class="stats"><article><div class="stat-head"><span>{{role==='admin'?'报名总数':'我的报名'}}</span><Users :size="17"/></div><strong>{{visibleRecords.length}}</strong><div class="stat-foot">当前浏览器记录</div></article><article><div class="stat-head"><span>审核通过率</span><CheckCircle2 :size="17"/></div><strong>{{passRate}}<span>%</span></strong><div class="stat-foot">{{passed}} 份已通过</div></article><article><div class="stat-head"><span>待检验 / 复核</span><CircleAlert :size="17"/></div><strong>{{visibleRecords.filter(r=>!['已通过','不通过'].includes(r.status)).length}}</strong><div class="stat-foot">AI 初筛 · 人工确认</div></article><article><div class="stat-head"><span>已评价平均分</span><Sparkles :size="17"/></div><strong>{{average}}</strong><div class="stat-foot">基于 {{evaluated.length}} 份示例报告</div></article></section><div class="overview-actions"><button class="quick-action coral" @click="navigate(role==='admin'?'verify':'register')"><span><Upload/><b>{{role==='admin'?'处理报名材料':'提交竞赛报名'}}</b><small>材料上传 · 一致性检验</small></span><ArrowUpRight/></button><button class="quick-action" @click="navigate('evaluate')"><span><Sparkles/><b>{{role==='admin'?'成果智能评价':'提交我的作品'}}</b><small>多维评价 · 教师复核</small></span><ArrowUpRight/></button><button class="quick-action" @click="exportRegistrations"><span><Download/><b>导出报名数据</b><small>真实本地记录 · CSV</small></span><ArrowUpRight/></button></div></template>
 <section v-if="['overview','verify','results'].includes(active)" class="panel records-panel"><div class="panel-head"><div><p class="eyebrow">REGISTRATION / {{role==='admin'?'VERIFICATION QUEUE':'MY APPLICATIONS'}}</p><h2>{{role==='admin'?'报名审核队列':'我的报名与进度'}}</h2></div><button class="text-btn" @click="exportRegistrations">导出 CSV <Download :size="15"/></button></div><div class="filters"><button v-for="s in ['全部状态','待检验','待复核','疑似异常','已通过','不通过']" :key="s" :class="{selected:filter===s}" @click="filter=s">{{s}}</button><label class="search-field"><Search :size="14"/><input v-model="query" placeholder="搜索姓名、学号、竞赛" aria-label="搜索报名记录"/></label></div><div class="table-wrap"><table><thead><tr><th>参赛者 / 学号</th><th>竞赛项目</th><th>材料</th><th>审核状态</th><th>提交时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><div class="person"><div class="mini-avatar">{{r.name[0]}}</div><div><b>{{r.name}}</b><small>{{r.studentId}}</small></div></div></td><td>{{contestName(r.contestId)}}</td><td>{{r.files.length}} 份材料</td><td><span class="status" :class="statusClass(r.status)"><i></i>{{r.status}}</span></td><td class="muted">{{time(r.submittedAt)}}</td><td><button class="row-btn" @click="openReview(r)">{{role==='admin'?'查看 / 复核':'查看进度'}} ↗</button></td></tr></tbody></table><div v-if="!filtered.length" class="empty-state"><ClipboardCheck :size="32"/><p>暂无符合条件的报名记录</p><button v-if="role==='student'" class="primary-btn" @click="navigate('register')">开始第一份报名 ↗</button></div></div></section>
 <section v-if="active==='competitions'" class="section-page"><div class="section-heading"><div><p class="eyebrow">FIND YOUR NEXT CHALLENGE</p><h1>{{role==='admin'?'竞赛管理':'发现你的下一场挑战'}}</h1></div><button v-if="role==='admin'" class="primary-btn" @click="editCompetition()"><Plus :size="17"/>发布竞赛</button></div><label class="search-field standalone-search"><Search :size="16"/><input v-model="query" placeholder="搜索竞赛、学科或状态" aria-label="搜索竞赛"/></label><p class="subtle-note">以下名称、日期与规则均为可编辑的演示配置，并非官方报名通知。</p><div class="competition-cards"><article v-for="(c,i) in competitions" :key="c.id"><div class="competition-visual" :class="'visual-'+i%4"><span>/ {{String(i+1).padStart(2,'0')}}</span><b>{{['MODEL','CODE','CREATE','DESIGN'][i%4]}}</b><i>✳</i></div><div class="competition-body"><small>{{c.category}}</small><h2>{{c.name}}</h2><p>{{c.description}}</p><div class="contest-meta"><span>{{c.phase}}</span><span>截止 {{c.deadline}}</span></div><p class="requirements">材料要求：{{c.requirements}}</p><button v-if="role==='admin'" class="primary-btn" @click="editCompetition(c)">编辑竞赛 / 报名配置 ↗</button><button v-else class="primary-btn" :disabled="!allowedRegistration(c)" @click="registerContest(c)">{{allowedRegistration(c)?'立即报名 ↗':'当前不可报名'}}</button></div></article></div><div v-if="!competitions.length" class="empty-state">未找到匹配的竞赛。</div></section>
 <section v-if="active==='register'" class="section-page"><div class="section-heading"><div><p class="eyebrow">01 / YOUR FIRST STEP</p><h1>在线报名</h1></div><span class="section-index">ENTER ↗</span></div><div class="form-layout"><form class="form-panel" @submit.prevent="submitRegistration"><div class="form-section-title"><b>01 基本信息</b><span>全部字段均为报名信息</span></div><label>选择竞赛<select v-model="registration.contestId" required><option v-for="c in state.competitions" :key="c.id" :value="c.id" :disabled="!allowedRegistration(c)">{{c.name}} · {{c.phase}}</option></select></label><div class="form-row"><label>姓名<input v-model="registration.name" required maxlength="30"/></label><label>学号<input v-model="registration.studentId" required inputmode="numeric" pattern="[0-9]{8,14}" readonly/></label></div><label>团队名称（选填）<input v-model="registration.team" maxlength="50" placeholder="给你的团队起个名字"/></label><div class="form-section-title"><b>02 证明信息</b><span>用于与材料识别结果比对</span></div><label>证书 / 证明名称<input v-model="registration.certificate" required/></label><div class="form-row"><label>获奖等级 / 无<input v-model="registration.award" required/></label><label>颁发单位<input v-model="registration.issuer" required/></label></div><div class="form-section-title"><b>03 报名材料</b><span>PNG / JPG / PDF · 20MB / 份</span></div><input ref="fileInput" class="hidden-input" type="file" multiple accept=".png,.jpg,.jpeg,.pdf" @change="pickFiles($event.target.files,'registration');$event.target.value=''"/><button type="button" class="dropzone" @click="fileInput.click()" @dragover.prevent @drop.prevent="pickFiles($event.dataTransfer.files,'registration')"><Upload :size="28"/><b>拖拽文件至此，或点击选择</b><small>最多 20 个文件</small></button><ul class="file-list"><li v-for="(f,i) in formFiles" :key="i"><span>{{f.name}} <small>{{(f.size/1024).toFixed(0)}} KB</small></span><button type="button" @click="formFiles.splice(i,1)" :aria-label="'移除 '+f.name"><X :size="14"/></button></li></ul><img v-if="preview&&formFiles.length" :src="preview" class="file-preview" alt="最近上传的图片预览"/><p class="subtle-note">本地演示只持久保存文件名和大小，不保存或上传文件原文。</p><button class="primary-btn" type="submit">提交报名，进入核验队列 <ArrowUpRight :size="17"/></button></form><aside class="form-aside"><span>REGISTRATION<br/>→ VERIFICATION<br/>→ CREATION</span><h2>把流程交给系统，<br/>把精力留给创造。</h2><p>填写的信息将与 OCR 提取字段进行一致性比对。姓名与学号严格匹配，异常结果进入教师复核队列。</p><ol><li>填写报名信息</li><li>上传清晰完整的证明</li><li>等待材料检验与人工复核</li><li>审核通过后提交作品</li></ol></aside></div></section>
 <section v-if="active==='evaluate'" class="section-page"><div class="section-heading"><div><p class="eyebrow">MULTIDIMENSIONAL EVALUATION</p><h1>{{role==='admin'?'成果智能评价':'提交你的作品'}}</h1></div><span class="section-index">CREATE ✳</span></div><template v-if="role==='student'"><form class="form-panel work-submit" @submit.prevent="submitWork"><label>已通过审核的报名<select v-model="work.registrationId" required><option disabled value="">请选择报名项目</option><option v-for="r in mine.filter(r=>r.status==='已通过')" :key="r.id" :value="r.id">{{contestName(r.contestId)}}</option></select></label><p v-if="!mine.some(r=>r.status==='已通过')" class="inline-warning">暂无审核通过的报名。请先报名，并在管理端演示中完成审核。</p><label>作品标题<input v-model="work.title" required maxlength="100" placeholder="给你的作品一个清晰的名字"/></label><label>作品摘要 / 不少于 20 字<textarea v-model="work.summary" required minlength="20" maxlength="10000" rows="6" placeholder="简述研究问题、实现方法、创新点与应用价值……"></textarea></label><input ref="workInput" class="hidden-input" type="file" multiple accept=".pdf,.docx,.txt,.zip,.png,.jpg,.jpeg" @change="pickFiles($event.target.files,'work');$event.target.value=''"/><button type="button" class="dropzone" @click="workInput.click()" @dragover.prevent @drop.prevent="pickFiles($event.dataTransfer.files,'work')"><Upload/><b>上传论文、报告或代码压缩包</b><small>PDF / DOCX / TXT / ZIP / 图片，20MB / 份</small></button><ul class="file-list"><li v-for="(f,i) in workFiles" :key="i"><span>{{f.name}}</span><button type="button" @click="workFiles.splice(i,1)" aria-label="移除作品文件"><X :size="14"/></button></li></ul><p class="subtle-note">仅保存文件元数据。此原型不会分析或上传作品内容。</p><button class="primary-btn">提交作品 ↗</button></form></template><template v-else><div class="evaluation-layout"><div class="work-list panel"><div class="panel-head"><h2>作品队列</h2><span>{{visibleWorks.length}} WORKS</span></div><button v-for="w in visibleWorks" :key="w.id" :class="{selected:selectedWorkId===w.id}" @click="selectedWorkId=w.id" :disabled="busy"><span>{{w.status}}</span><strong>{{w.title}}</strong><small>{{w.name}} / {{contestName(w.contestId)}}</small></button><div v-if="!visibleWorks.length" class="empty-state">暂无作品，学生端提交后将显示在此。</div></div><article v-if="selectedWork" class="evaluation-report form-panel"><p class="eyebrow">EVALUATION REPORT / DEMO</p><h2>{{selectedWork.title}}</h2><p class="report-summary">{{selectedWork.summary}}</p><div class="file-chips"><span v-for="f in selectedWork.files" :key="f.name">{{f.name}}</span></div><p class="inline-warning">演示模式使用固定评分与示例评语，不解析上传文件。真实评价需要接入 FastAPI 和大模型服务。</p><ElProgress v-if="busy" :percentage="runProgress" color="#f40c3f"/><button class="primary-btn" :disabled="busy||!!selectedWork.aiScores" @click="runEvaluation">{{selectedWork.aiScores?'示例评价已生成':'生成示例评价'}} <Sparkles :size="16"/></button><template v-if="selectedWork.aiScores"><div class="report-score"><span>{{score(selectedWork.finalScores||selectedWork.aiScores,selectedWork.weights).toFixed(1)}}</span><div>综合得分 / 100<br/><small>{{selectedWork.status}}</small></div></div><div class="dimension-score" v-for="(d,i) in dimensions" :key="d"><label>{{d}} <small>权重 {{selectedWork.weights[i]}}% · AI 示例 {{selectedWork.aiScores[i]}}</small></label><div class="dimension-bar"><i :style="{width:reviewScores[i]+'%'}"></i></div><ElInputNumber v-model="reviewScores[i]" :min="0" :max="100" :precision="0" size="small" :aria-label="d+'复核分数'"/></div><label>教师复核意见<textarea v-model="reviewComments" rows="4"></textarea></label><div class="button-row"><button class="primary-btn" @click="saveReview">保存教师复核</button><button class="outline-btn" :disabled="selectedWork.status!=='已复核'" @click="publish">{{selectedWork.published?'已发布':'发布成绩'}}</button><button class="outline-btn" @click="exportReport(selectedWork)">导出报告</button></div></template><div v-if="selectedWork.history.length" class="audit-log"><h3>评价与复核记录</h3><p v-for="(h,i) in selectedWork.history" :key="i"><small>{{time(h.at)}} / {{h.action}}</small>{{h.note}}</p></div></article><div v-else class="empty-state panel"><Sparkles :size="42"/><h2>选择一份作品，开始评价。</h2><p>创新性 · 技术实现 · 完成度 · 应用价值</p></div></div></template></section>
 <section v-if="active==='results'" class="section-page"><div class="section-heading"><div><p class="eyebrow">MY ACHIEVEMENTS</p><h1>我的作品与评价</h1></div></div><div v-if="!visibleWorks.length" class="empty-state panel"><Trophy :size="35"/><p>还没有提交作品。报名审核通过后即可提交。</p><button class="primary-btn" @click="navigate('evaluate')">提交作品 ↗</button></div><article v-for="w in visibleWorks" :key="w.id" class="result-card panel"><span class="status" :class="statusClass(w.status)">{{w.status}}</span><h2>{{w.title}}</h2><p>{{contestName(w.contestId)}}</p><template v-if="w.published"><div class="report-score"><span>{{score(w.finalScores,w.weights).toFixed(1)}}</span><small>综合得分 / 100</small></div><div class="result-dimensions"><div v-for="(d,i) in dimensions" :key="d"><span>{{d}}</span><strong>{{w.finalScores[i]}}</strong></div></div><p>{{w.comments}}</p><button class="outline-btn" @click="exportReport(w)">导出评价报告</button></template><p v-else class="subtle-note">教师完成复核并发布后，评价分数与评语将在这里展示。</p></article></section>
 <section v-if="active==='students'&&role==='admin'" class="section-page"><div class="section-heading"><div><p class="eyebrow">PARTICIPANTS / LOCAL DATA</p><h1>参赛学生</h1></div><button class="outline-btn" @click="downloadCsv('竞序_参赛学生.csv',['姓名','学号','报名数','通过数'],participants.map(p=>[p.name,p.id,p.count,p.passed]))">导出学生名单</button></div><label class="search-field standalone-search"><Search :size="16"/><input v-model="query" placeholder="搜索姓名或学号" aria-label="搜索学生"/></label><div class="panel table-wrap"><table><thead><tr><th>姓名</th><th>学号</th><th>报名竞赛数</th><th>审核通过数</th></tr></thead><tbody><tr v-for="p in participants" :key="p.id"><td>{{p.name}}</td><td>{{p.id}}</td><td>{{p.count}}</td><td>{{p.passed}}</td></tr></tbody></table><div v-if="!participants.length" class="empty-state">未找到匹配的学生。</div></div></section>
 <footer class="footer-sign"><span>WU ZHILIANG / GRADUATION PROJECT 2026</span><span>COMPETE · LOCAL DEMO <b>↗</b></span></footer>
 </div></main>
 <ElDialog v-model="reviewOpen" :title="role==='admin'?'材料检验与人工复核':'报名详情与进度'" width="760px" class="review-dialog" :close-on-click-modal="false" :before-close="done=>{if(!busy)done()}"><template v-if="detail"><div class="review-identity"><b>{{detail.name}} / {{detail.studentId}}</b><span>{{contestName(detail.contestId)}} · {{detail.status}}</span></div><div class="file-chips"><span v-for="f in detail.files" :key="f.name">{{f.name}}</span></div><template v-if="role==='admin'"><p class="inline-warning">此原型仅载入示例 OCR 字段，不读取图片或 PDF 原文。可编辑字段，验证通过、可疑、不通过的前端流程。</p><ElProgress v-if="busy" :percentage="runProgress" color="#f40c3f"/><button class="primary-btn" :disabled="busy" @click="startScan">{{busy?'正在演示识别流程…':'载入示例识别字段'}}</button><div v-if="scanReady&&!busy" class="ocr-fields"><label v-for="(label,key) in fieldLabels" :key="key">{{label}}<input v-model="ocr[key]" :aria-label="'识别'+label"/><small>申报值：{{detail[key]||'未填写'}}</small></label><button class="outline-btn" @click="compare">执行一致性比对</button></div><div v-if="detail.checks" class="check-results"><div v-for="c in detail.checks" :key="c.key" :class="c.match?'check-pass':'check-fail'"><span>{{fieldLabels[c.key]}}</span><span>{{c.expected}} → {{c.actual||'缺失'}}</span><b>{{c.match?'一致':'需核对'}}</b></div></div><label class="review-note">人工复核意见（必填）<textarea v-model="reviewNote" rows="3" placeholder="记录判断依据或需要补充的材料"></textarea></label><div class="button-row"><button class="primary-btn" :disabled="busy" @click="resolveReview('已通过')">审核通过</button><button class="outline-btn" :disabled="busy" @click="resolveReview('不通过')">不通过 / 需重新报名</button></div></template><div class="audit-log"><h3>处理记录</h3><p><small>{{time(detail.submittedAt)}} / 报名提交</small>材料已进入核验队列</p><p v-for="(h,i) in detail.history" :key="i"><small>{{time(h.at)}} / {{h.action}}</small>{{h.note}}</p></div></template></ElDialog>
 <ElDialog v-model="settingsOpen" title="评价规则设置" width="540px"><p>各维度按 0–100 分评分；权重合计须为 100%。</p><div class="weight-row" v-for="(d,i) in dimensions" :key="d"><span>{{d}}</span><ElInputNumber v-model="settingsWeights[i]" :min="0" :max="100" :precision="0" :aria-label="d+'权重'"/> %</div><p>合计：{{settingsWeights.reduce((s,x)=>s+(x||0),0)}}%</p><div class="button-row"><button class="primary-btn" @click="saveSettings">保存规则</button><button class="outline-btn" @click="reset">重置演示数据</button></div></ElDialog>
 <ElDialog v-model="competitionModal" :title="editingId?'编辑竞赛':'发布竞赛'" width="600px"><form class="dialog-form" @submit.prevent="saveCompetition"><label>竞赛名称<input v-model="competition.name" required maxlength="100"/></label><div class="form-row"><label>学科分类<input v-model="competition.category" required/></label><label>报名截止<input v-model="competition.deadline" type="date" required/></label></div><label>当前阶段<select v-model="competition.phase"><option>即将开始</option><option>报名中</option><option>评审中</option><option>已结束</option></select></label><label>竞赛说明<textarea v-model="competition.description" rows="3" required></textarea></label><label>材料与报名要求<textarea v-model="competition.requirements" rows="2"></textarea></label><button class="primary-btn">保存竞赛配置</button></form></ElDialog>
 <ElDialog v-model="notificationOpen" title="待办通知" width="480px"><template v-if="role==='admin'"><button class="notification-card" v-for="n in notifications" :key="n.title" @click="notificationOpen=false;navigate(n.target)"><b>{{n.title}} ↗</b><span>{{n.body}}</span></button></template><p v-else>你的报名与作品进度可在“我的结果”中查看。</p></ElDialog>
</div>
</template>
